  "implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    distances = case['distances']
    n = len(nodes)
    edges_raw = []
    for a, b, d in distances:
        core_a = core[a]
        core_b = core[b]
        mutual = max(core_a, core_b, d)
        if a > b:
            a, b = b, a
        edges_raw.append((mutual, a, b))
    edges_raw.sort(key=lambda e: (e[0], e[1], e[2]))
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total_weight = 0.0
    for w, a, b in edges_raw:
        if union(a, b):
            mst_edges.append({'source': a, 'target': b, 'weight': w})
            total_weight += w
            if len(mst_edges) == n - 1:
                break
    if len(mst_edges) != n - 1:
        raise ValueError('Graph is disconnected')
    return {'edges': mst_edges, 'total_weight': total_weight}"
}
